sysauto_script.script:
(function executeRule(current, previous /*null when async*/) {

    var IMPLEMENT = "-1";
    var REVIEW = 0;
    var SCHEDULED = "-2";

    var gr = new GlideRecord("change_request");
    gr.addQuery("category", "CSA Configuration");
    gr.addQuery("state", SCHEDULED);
    gr.query();

    var now = new GlideDateTime();

    while (gr.next()) {
        var start = new GlideDateTime(gr.getValue("start_date"));
        var end = new GlideDateTime(gr.getValue("end_date"));

        if (now.after(start) && now.before(end)) {
            gs.info("Processing CR: " + gr.number);

            try {
                // === Get values from CR ===
                var destListSysId = gr.getValue("u_destination_list") || "";
                var destName = gr.u_destination_list.getDisplayValue();
                var destAddr = gr.getValue("u_destination_address");

                // Initialize variable for u_list_id
                var destListId = "";
                if (destListSysId) {
                    var destGR = new GlideRecord("u_destination_list");
                    if (destGR.get(destListSysId)) {
                        destListId = destGR.getValue("u_list_id"); 
                    }
                }

                var comment = "Added by user: " + gr.opened_by +
                    " as part of change ticket: " + gr.number;

                // === Get latest access token from token table ===
                var tokenGR = new GlideRecord("x_1803242_sample_u_cisco_csa_token");
                tokenGR.orderByDesc("sys_created_on");
                tokenGR.setLimit(1);
                tokenGR.query();

                if (!tokenGR.next()) {
                    gs.error("No access token found in x_1051972_cisco_cs_cisco_csa_token table");
                    return;
                }

                var accessToken = tokenGR.getValue("access_token");
                if (!accessToken) {
                    gs.error("Access token is empty in record");
                    return;
                }

                // === Build payload for Add Destination API ===
                var rawBodyArr = [];
                var destArray = [];
                if (destAddr) {
                    destArray = destAddr.split(",");
                    for (var i = 0; i < destArray.length; i++) {
                        var addr = destArray[i].trim();
                        if (addr) {
                            rawBodyArr.push({
                                destination: addr,
                                comment: comment
                            });
                        }
                    }
                }

                var rawBody = JSON.stringify(rawBodyArr);

                var endpoint = "https://api.sse.cisco.com/policies/v2/destinationlists/" + destListId + "/destinations";

                gs.info("Destination list ID: " + destListId);
                gs.info("Destination List Name: " + destName);
                gs.info("Destination Address: " + destAddr);
                gs.info("Endpoint: " + endpoint);
                gs.info("Payload: " + rawBody);

                // === Call REST API ===
                var resp = sendRest(endpoint, accessToken, rawBody, gr.number);
                gs.info("Response object: " + JSON.stringify(resp));

                // === Process response ===
                if (resp.success) {
                    gs.info("Response success, moving CR " + gr.number + " to REVIEW state");
                    gr.setWorkflow(false);
                    gr.state = REVIEW;
                    gr.work_notes = resp.message;
                    gr.update();

                    // === Insert into u_destinations table (one per address) ===
                    for (var j = 0; j < destArray.length; j++) {
                        var addrVal = destArray[j].trim();
                        if (addrVal) {
                            var destInsert = new GlideRecord("u_destinations");
                            destInsert.initialize();
                            destInsert.u_destination = addrVal;       
                            destInsert.u_comment = comment;          
                            destInsert.u_ticket_id = gr.number;       
                            destInsert.u_destination_list_id = destListSysId;
                            var newId = destInsert.insert();
                            gs.info("Inserted into u_destinations, sys_id: " + newId);
                        }
                    }

                } else if (resp.message && resp.message.toLowerCase().indexOf("destination list full") !== -1) {
                    gs.info("Destination list is full, raising alert and moving CR " + gr.number + " to IMPLEMENT state");

                    gr.state = IMPLEMENT;
                    gr.work_notes = "Destination list full";
                    gr.update();

                    var event = new GlideRecord("em_event");
                    event.initialize();
                    event.source = "Custom Script";
                    event.node = "CSA_Config";
                    event.resource = "Destination List";
                    event.type = "Error";
                    event.metric_name = "Destination List Full";
                    event.severity = 2;
                    event.description = "Destination list full for CR " + gr.number;
                    var eventId = event.insert();
                    gs.info("Event created: " + eventId);

                } else {
                    gs.info("Response failed, moving CR " + gr.number + " to IMPLEMENT state");
                    gr.state = IMPLEMENT;
                    gr.work_notes = "Failed: " + resp.message;
                    gr.update();
                }

            } catch (ex) {
                var message = ex.message || ex.toString();
                gs.error("Exception while processing CR " + gr.number + ": " + message);

                gr.state = IMPLEMENT;
                gr.work_notes = "Exception occurred: " + message;
                gr.update();
            }
        }
    }

    // === Helper function to call Cisco Add Destination API ===
    function sendRest(endpoint, accessToken, rawBody, changeNum) {
        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(endpoint);
            r.setHttpMethod("POST");
            r.setRequestHeader("Authorization", "Bearer " + accessToken);
            r.setRequestHeader("Content-Type", "application/json");
            r.setRequestBody(rawBody);

            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();

            gs.info("CR " + changeNum + " | HTTP Status: " + status + " | Body: " + body);

            var parsed;
            try {
                parsed = JSON.parse(body);
            } catch (e) {
                return { success: false, message: "Invalid JSON response: " + body };
            }

            if (status >= 200 && status < 300) {
                return {
                    success: true,
                    message: "Destination added successfully for CR " + changeNum,
                    data: parsed.data
                };
            } else {
                return {
                    success: false,
                    message: "Cisco API error | HTTP " + status + " | Body: " + body
                };
            }
        } catch (e) {
            return { success: false, message: e.message || e.toString() };
        }
    }

})(current, previous);
